#' Time Series
#'
#' 
#' @param data .
#' @param series Select the numeric variable(s) representing the time series
#'   to evaluate. Univariate models (ARIMA, SARIMA, ETS, GARCH) use a single
#'   series; multivariate models (VAR, VECM) allow several.
#' @param dateVar Optional variable with the date or timestamp of each
#'   observation, used only to label the plots' horizontal axis. It is not
#'   required: if none is selected, Time Series assumes regularly spaced
#'   observations following row order and the declared periodicity, and labels
#'   the axis with the observation index (1, 2, 3, ...). This variable is not
#'   used to check for gaps or irregularities in the time spacing.
#' @param exogenous External numeric variables to include as model regressors
#'   (ARIMAX if the model is ARIMA, SARIMAX if it is SARIMA). Does not apply to
#'   ETS, VAR, VECM, or GARCH. If left empty, the model is fit without external
#'   regressors, as standard ARIMA/SARIMA.
#' @param model Select the time-series modeling approach to display the
#'   relevant statistical and methodological conditions, and to run the minimum
#'   recommended set of diagnostics for that model.
#' @param frequency Number of observations per seasonal cycle (12 = monthly, 4
#'   = quarterly, 7 = daily with a weekly cycle, 1 = no seasonality). Used for
#'   seasonal tests and differencing in SARIMA and ETS.
#' @param reportLang .
#' @param showPlots .
#' @param plotStyle Visual style of the plots (background, line type): clean
#'   academic, black and white for print, high contrast for accessibility, or
#'   full color. Purely cosmetic; does not affect any computed value.
#' @param plotPalette Palette used to distinguish several series in the same
#'   plot (for example, the variables of a VAR/VECM). Includes a colorblind-safe
#'   option for accessibility.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$modelProfile} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$modelDescription} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$conditionsMatrix} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$decisionsMatrix} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$runNotice} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$seriesPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$diagnosticsResults} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$acfPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$pacfPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$residualsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$volatilityPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$foundations} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$diagnosticsActions} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$implementationNotes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$modelProfile$asDF}
#'
#' \code{as.data.frame(results$modelProfile)}
#'
#' @export
timeCheck <- function(
    data,
    series,
    dateVar,
    exogenous,
    model = "sarima",
    frequency = 12,
    reportLang = "en",
    showPlots = TRUE,
    plotStyle = "clean",
    plotPalette = "blueOrange") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("timeCheck requires jmvcore to be installed (restart may be required)")

    if ( ! missing(series)) series <- jmvcore::resolveQuo(jmvcore::enquo(series))
    if ( ! missing(dateVar)) dateVar <- jmvcore::resolveQuo(jmvcore::enquo(dateVar))
    if ( ! missing(exogenous)) exogenous <- jmvcore::resolveQuo(jmvcore::enquo(exogenous))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(series), series, NULL),
            `if`( ! missing(dateVar), dateVar, NULL),
            `if`( ! missing(exogenous), exogenous, NULL))


    options <- timeCheckOptions$new(
        series = series,
        dateVar = dateVar,
        exogenous = exogenous,
        model = model,
        frequency = frequency,
        reportLang = reportLang,
        showPlots = showPlots,
        plotStyle = plotStyle,
        plotPalette = plotPalette)

    analysis <- timeCheckClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

